{
  "technical_and_design_decisions": [
    "Target stack: Java 17 with Spring Framework 6 / Spring Boot 3, developed as Maven modules inside the existing spring-cloud-stream (s-c-s) and spring-cloud-data (s-c-d) repositories.",
    "U1: deliver test support as a dedicated test-support module providing an in-memory test Binder implementing the existing Binder SPI, a MessageCollector to capture module output, and Hamcrest-based matcher/assertion utilities, so module wiring and @ConfigurationProperties combinations can be tested without a real broker (redis, rabbit, etc.).",
    "U4: implement the Redis binder against the existing Binder SPI on top of Spring Data Redis (pub/sub), with Redis Sentinel cluster topology configured via externalized binder properties.",
    "U2 is treated as a time-boxed spike: research plus a throwaway prototype on a YARN mini-cluster whose output is the documented strategy for YARNModuleDeployer; a production-grade YARN deployer is out of scope for this increment.",
    "U3: port the XD trigger module to the s-c-s annotation-based source model so it is a buildable, testable source module for streaming pipelines.",
    "U5: isolate the upgraded receptor-client behind a thin adapter layer so future Receptor API changes remain localized; adapt dependent deployer code to the new API.",
    "U6: reuse the existing admin UI client assets and wire them to the spring-cloud-data admin server through externalized server configuration; no new UI development.",
    "U7: implement singlenode binder auto-configuration following Spring Boot conventions (auto-configuration class, @ConfigurationProperties, registration metadata, conditional activation based on classpath/dependencies).",
    "U8: pass definition parameters into YARN containers as environment variables and command-line arguments, resolved by the deployer at container-launch time so modules can consume them via standard property binding."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are pure effort in work-hours, not elapsed calendar duration.",
    "The existing s-c-s / s-c-d codebases, source control, build tooling, and CI infrastructure are available and functioning; no procurement or environment setup effort is included beyond the stated build-alignment activity.",
    "Definition of done per activity: implementation complete, code reviewed, unit tests passing, and relevant reference documentation updated.",
    "Test infrastructure (embedded Redis, YARN mini-cluster, a test Receptor endpoint) is available locally or in CI at no additional cost.",
    "User stories are stable; minor ambiguities (e.g., exact assertion API shape in U1, exact parameter passing mechanism in U8) are resolved by developer judgment without formal change control.",
    "Prior Spring XD code referenced by U3 and U5 is accessible and its license permits reuse and modification.",
    "U2 delivers an investigation report and prototype only; the production YARNModuleDeployer implementation is a later increment.",
    "Effort excludes production deployment, release management, and post-release maintenance; per-activity unit testing is included, with one cross-cutting end-to-end integration and hardening activity."
  ],
  "activities": [
    {
      "activity_id": "0.1",
      "activity_name": "Increment build and dependency alignment",
      "activity_description": "Align Maven builds, dependency versions, and CI jobs across the affected s-c-s and s-c-d modules so all user-story work proceeds on a consistent baseline.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "1.1",
      "activity_name": "U1 - Design test-support API",
      "activity_description": "Design the test-support module API: in-memory test Binder contract, MessageCollector, property-combination testing hooks, and the idiomatic Hamcrest-based assertion style.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "1.2",
      "activity_name": "U1 - Implement in-memory test binder",
      "activity_description": "Implement the in-memory test Binder so module wiring is fully testable without sending data to an actual bus (redis, rabbit, etc.).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "1.3",
      "activity_name": "U1 - Implement message collector and Hamcrest assertion utilities",
      "activity_description": "Implement utilities to send data into a module, capture what comes out the other end, and assert on it idiomatically via Hamcrest matchers.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "1.4",
      "activity_name": "U1 - Configuration properties test support",
      "activity_description": "Enable @ConfigurationProperties to be in effect during tests and support testing various combinations of property values.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "1.5",
      "activity_name": "U1 - Unit and integration tests for test-support module",
      "activity_description": "Write unit and integration tests covering binder behavior, property combinations, and assertion utilities.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "1.6",
      "activity_name": "U1 - Documentation and sample usage",
      "activity_description": "Document the test-support module and provide a sample module test demonstrating send/assert usage.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "2.1",
      "activity_name": "U2 - Research YARN deployment model and SPI integration points",
      "activity_description": "Investigate distributed deployment of s-c-s modules on YARN: container lifecycle, resource negotiation, and SPI extension points relevant to a module deployer.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "2.2",
      "activity_name": "U2 - Prototype distributed module deployment on YARN mini-cluster",
      "activity_description": "Build a throwaway prototype deploying s-c-s modules to a YARN mini-cluster to validate the SPI approach and surface constraints.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "2.3",
      "activity_name": "U2 - Document findings and YARNModuleDeployer strategy",
      "activity_description": "Write up investigation results and derive the implementation strategy for YARNModuleDeployer.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "3.1",
      "activity_name": "U3 - Port trigger module from XD to s-c-s source model",
      "activity_description": "Move the trigger module code from the XD repository into the s-c-s repository and adapt it to the annotation-based source model so it can be used as a source in streaming pipelines.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "3.2",
      "activity_name": "U3 - Trigger module tests and build integration",
      "activity_description": "Add tests for the ported trigger source and integrate the module into the s-c-s build and CI.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "4.1",
      "activity_name": "U4 - Design Redis binder",
      "activity_description": "Design the Redis binder (pub/sub producer/consumer model, error handling, and property surface) so it can serve as the message bus for streams and batch pipelines.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "4.2",
      "activity_name": "U4 - Implement Redis binder core",
      "activity_description": "Implement the core Redis binder against the Binder SPI using Spring Data Redis.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "4.3",
      "activity_name": "U4 - Implement Redis Sentinel cluster support",
      "activity_description": "Add Sentinel-aware connection configuration so users can run the binder against a redis/sentinel cluster.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "4.4",
      "activity_name": "U4 - Redis binder integration tests",
      "activity_description": "Write integration tests against embedded Redis and a Sentinel topology covering stream and batch pipeline usage.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "4.5",
      "activity_name": "U4 - Redis binder documentation",
      "activity_description": "Document Redis/Sentinel binder configuration properties and usage for streams and batch pipelines.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "5.1",
      "activity_name": "U5 - Upgrade receptor-client to latest Receptor API",
      "activity_description": "Update the receptor-client to comply with the latest Receptor API changes, isolating the changes behind an adapter layer.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "5.2",
      "activity_name": "U5 - Adapt dependent code and regression tests",
      "activity_description": "Adapt deployer code that consumes receptor-client and add regression tests verifying behavior against the new API.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "6.1",
      "activity_name": "U6 - Integrate existing admin UI with spring-cloud-data admin server",
      "activity_description": "Wire the existing admin UI client to the spring-cloud-data admin server so it works with the appropriate server configurations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "6.2",
      "activity_name": "U6 - Externalized configuration and tests",
      "activity_description": "Add externalized server configuration options for the admin UI integration and cover them with tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "7.1",
      "activity_name": "U7 - Implement singlenode binder auto-configuration and properties",
      "activity_description": "Create the auto-configuration class and @ConfigurationProperties for the singlenode binder so the Spring application is configured automatically based on dependencies.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "7.2",
      "activity_name": "U7 - Auto-configuration registration and tests",
      "activity_description": "Register the auto-configuration via Spring Boot metadata and add conditional-activation tests for classpath/dependency combinations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "8.1",
      "activity_name": "U8 - Implement definition-parameter passing into YARN containers",
      "activity_description": "Add support for passing stream definition parameters into the YARN container (environment variables and command-line arguments) so modules running inside the container can use them.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "8.2",
      "activity_name": "U8 - Tests for YARN parameter passing",
      "activity_description": "Add unit and integration tests verifying that definition parameters are propagated and bound correctly inside the container.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "9.1",
      "activity_name": "Cross-cutting end-to-end integration, review rework, and hardening",
      "activity_description": "Perform end-to-end verification across all delivered stories (test-support module, Redis/Sentinel binder, trigger source, admin UI, auto-configuration, YARN-related changes), incorporate review feedback, and stabilize the increment.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 372
  }
}

